program MapFilter(output);
{ ISO 7185 lets functions be passed as parameters (but has no closures). }
type
  IntArray = array[1..10] of integer;
var
  xs: IntArray;
  i: integer;

function isEven(x: integer): boolean; begin isEven := not odd(x) end;
function square(x: integer): integer; begin square := x * x end;

procedure filterMap(var a: IntArray; function keep(x: integer): boolean;
                    function f(x: integer): integer);
var i: integer; first: boolean;
begin
  first := true;
  for i := 1 to 10 do
    if keep(a[i]) then begin
      if not first then write(' ');
      write(f(a[i]):1);
      first := false
    end;
  writeln
end;

begin
  for i := 1 to 10 do xs[i] := i;
  filterMap(xs, isEven, square)
end.

