program Shapes(output);
type
  ShapeKind = (Rectangle, Triangle);
  Shape = record                        { a variant record: Pascal's sum type }
    case kind: ShapeKind of             { the tag field selects the variant }
      Rectangle: (width, height: integer);
      Triangle:  (base, altitude: integer)
  end;
var
  r, t: Shape;

function area(s: Shape): integer;
begin
  case s.kind of
    Rectangle: area := s.width * s.height;
    Triangle:  area := s.base * s.altitude div 2
  end
end;

procedure show(s: Shape);
begin
  case s.kind of
    Rectangle: write('Rectangle: ');
    Triangle:  write('Triangle: ')
  end;
  writeln(area(s):1)
end;

begin
  with r do begin kind := Rectangle; width := 3; height := 4 end;
  with t do begin kind := Triangle; base := 10; altitude := 3 end;
  show(r); show(t)
end.

