program Week(output);
{ Wirth's "data structuring": enumerations, subranges, sets
  and arrays indexed by any ordinal type -- all type-checked. }
type
  Day   = (Mon, Tue, Wed, Thu, Fri, Sat, Sun);
  Hours = 0..24;                         { a subrange type }
var
  d: Day;
  worked: array[Day] of Hours;           { indexed by an enumeration }
  weekend, workdays: set of Day;
  days, total: integer;
begin
  weekend := [Sat, Sun];
  workdays := [Mon..Sun] - weekend;      { set difference }
  days := 0; total := 0;
  for d := Mon to Sun do begin
    if d in workdays then begin worked[d] := 8; days := days + 1 end
    else worked[d] := 0;
    total := total + worked[d]
  end;
  if succ(Tue) = Wed then writeln('succ(Tue) = Wed, ord(Sun) = ', ord(Sun):1);
  writeln('workdays: ', days:1, ', hours: ', total:1)
end.
